const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty=v=>JSON.stringify(v,(k,x)=>typeof x==='function'?'[Calculation]':x,2);
const fetchJSON=async u=>{const compressed=u.endsWith('.snapshot.json')&&!u.endsWith('/hh.snapshot.json');const actual=compressed?u+'.gz':u;const r=await fetch(actual);if(!r.ok)throw Error(`Could not load ${actual}: ${r.status}`);if(compressed&&r.headers.get('Content-Encoding')!=='gzip')return unpackSnapshot(await new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).json());return unpackSnapshot(await r.json());};
const baseURL=new URL('./',location.href),catalog=await fetchJSON('data/catalog.json'),proof=await fetchJSON('data/delta-proof.json');
const atlasView=createAtlasView({implementationIdentity:catalog.release?.atlasIdentity});
const block5View=createBlock5View();
const hh=createHHWorkbench({storageKey:'composed-workbench-hh-fixture-v1'}),capabilities=hh.listCapabilities(),workflows=hh.listWorkflows();
let route=parseRoute(location.hash,catalog.projects),selectedCapability=capabilities[0].id,selectedWorkflow=workflows[0].id,lastResult=null,deltaBase=null,deltaTarget=null,lastPatch=null,deltaMessage='',composeDraft='',testsResult=null;
const snapshots=new Map();let swReady=false;
try{if('serviceWorker'in navigator){await navigator.serviceWorker.register('sw.js');await navigator.serviceWorker.ready;if(!navigator.serviceWorker.controller)await new Promise(resolve=>{navigator.serviceWorker.addEventListener('controllerchange',resolve,{once:true});setTimeout(resolve,2500);});swReady=!!navigator.serviceWorker.controller;}}catch(e){deltaMessage=`Browser local compiled storage unavailable: ${e.message}`;}
async function snapshot(id){if(!snapshots.has(id)){const s=await fetchJSON(`data/${id}.snapshot.json`);await validateSnapshot(s);snapshots.set(id,s);}return snapshots.get(id);}
function output(v){const cleaned=v?.result??v;if(v?.outcomes)return {ok:v.ok,name:v.name,outcome:v.outcome,stages:v.outcomes.map(s=>({id:s.id,operation:s.operation,ok:s.ok,result:s.result})),outerReceipt:v.receipt?{status:v.receipt.status,into:v.receipt.into,inputNames:Object.keys(v.receipt.composition?.inputs??{})}:null};return cleaned;}
function shell(){atlasView.unmount();block5View.unmount();const p=catalog.projects.find(x=>x.id===route.project);$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="mark">◈</span>Composed</div><div class="eyebrow">Page Router × PxCube</div><div class="group-label">Pinned projects</div><div class="projects">${catalog.projects.map(x=>`<a class="project ${x.id===p.id?'active':''}" href="${routeFor(x.id)}"><strong>${esc(x.title)}</strong><small>${esc(x.pin)}</small></a>`).join('')}</div><div class="sidebar-note"><span class="dot"></span>Browser-local runtime<br>Existing neat owns work<br>tidy owns registration<br>crisp owns package execution<br><br>Exact compiled pins. Visible evidence. Disposable fixture state.</div></aside><main class="main"><header class="topbar"><span class="crumb">Projects / ${esc(p.title)} / ${esc(route.view)}</span><span class="top-status"><span class="dot"></span>LOCAL · v${esc(catalog.release?.version??'unversioned')} ${esc(catalog.release?.channel??'')} · ${(catalog.release?.siteBuildId??catalog.release?.buildId)?.slice(0,10)??''}<span style="margin-left:10px;color:#647f95">double-click for release notes</span></span></header><div class="content"><div class="hero"><div><div class="kicker">Layered composed workbench</div><h1>${esc(p.title)}</h1><p>${esc(p.subtitle)}. Display the actual compiled project, expose its functionality, run it separately, then compose and inspect real execution.</p></div><span class="badge">PINNED ${p.digest.slice(0,12)}</span></div><nav class="tabs">${[['overview','Overview'],['run','Display & run'],['compare','Side by side'],['functions','Functionality'],...(p.id==='pxcube'?[['atlas','Atlas'],['block5','Block5']]:[]),['compose','Composition'],['delta','Delta builds'],['scope','Scope & evidence'],...(p.id==='justin'?[['audit','Audit']]:[])].map(([v,label])=>`<a href="${routeFor(p.id,v)}" class="${v===route.view?'active':''}">${label}</a>`).join('')}</nav><section id="view"></section><dialog id="release-notes"><div class="row spread"><h2>Release ${esc(catalog.release?.version??'unknown')}</h2><button id="close-release">Close</button></div><p class="mono">Derived from ${esc(catalog.release?.record??'existing source records')}</p><ul>${(catalog.release?.notes??[]).map(n=>`<li>${esc(n)}</li>`).join('')}</ul><details><summary>Exact pins and linked receipts</summary><pre>${esc(pretty({siteBuildId:catalog.release?.siteBuildId??catalog.release?.buildId,implementationPin:catalog.release?.buildId,evaluatorIdentity:catalog.release?.evaluatorIdentity,projects:catalog.projects.map(x=>({id:x.id,pin:x.pin,digest:x.digest,source:x.source})),packages:catalog.pxcubeResults.map(x=>({id:x.id,sourceHash:x.sourceHash,receipt:x.receipt}))}))}</pre></details></dialog><div class="footer">Source truth: <a href="${esc(p.source)}" target="_blank" rel="noopener">${esc(p.pin)}</a> · compiled SHA-256 ${p.digest}<br>Human acceptance stays separate from executable checks. Recovered PageRouter source: samuelpmahan/PageRouter @5cc1ae3d8d4d. Original comparison preserved alongside the new workbench.</div></div></main></div>`;renderView(p);$('.top-status').ondblclick=()=>$('#release-notes').showModal();$('#close-release').onclick=()=>$('#release-notes').close();}
function renderView(p){if(route.view==='atlas')atlasView.mount($('#view'));if(route.view==='block5')block5View.mount($('#view'));if(route.view==='overview')overview(p);if(route.view==='run')runView(p);if(route.view==='compare')compareView(p);if(route.view==='functions')functionsView(p);if(route.view==='compose')composeView(p);if(route.view==='delta')deltaView(p);if(route.view==='scope')scopeView(p);if(route.view==='audit')auditView(p);}
function overview(p){$('#view').innerHTML=`<div class="grid"><div class="panel"><div class="kicker">Compiled artifact</div><div class="big">${p.fileCount}</div><div class="metric-note">Pinned files · ${(p.bytes/1024/1024).toFixed(2)} MB</div></div><div class="panel"><div class="kicker">Actual functionality</div><div class="big">${p.id==='hh'?capabilities.length:p.id==='pxcube'?catalog.pxcubeResults.filter(x=>x.ok).length:6}</div><div class="metric-note">${p.id==='hh'?'Fixture ports with real Parts & receipts':p.id==='pxcube'?'Existing crisp packages with verified chunks':'Standalone navigable pages'}</div></div><div class="panel"><div class="kicker">Delta acceptance</div><div class="big proof">Exact</div><div class="metric-note">Local patched HH artifact = clean compiled output</div></div></div><div class="section-title"><h2>The whole ladder</h2><span>One aggregation, explicit seams</span></div><div class="ladder"><div><span class="num">01 · PAGE ROUTER</span><strong>Pinned projects</strong><p>Three actual project artifacts. Hash routes and browser history retain the selected layer.</p></div><div><span class="num">02 · PXCUBE</span><strong>Display and inspect</strong><p>The recovered full launcher and ${catalog.pxcubeResults.filter(x=>x.ok).length} sandboxed crisp-packaged experiences retain neat/tidy provenance.</p></div><div><span class="num">03 · FUNCTIONALITY</span><strong>Run and compose</strong><p>Fourteen HH fixture service ports, five presets, editable ref-bound pipelines and kernel receipts.</p></div><div><span class="num">04 · COMPILED DELTA</span><strong>Build, import, verify</strong><p>Declared dependency closure, reused outputs, minimal single byte-span patch and exact-base rejection.</p></div></div><div class="section-title"><h2>${p.id==='pxcube'?'Actual experiences':p.id==='hh'?'Composable fixture functionality':'Standalone leaf'}</h2><a href="${routeFor(p.id,'run')}">Open project →</a></div>${p.id==='pxcube'?`<div class="notice"><strong>Executable Atlas</strong> · Run live program search, retain failures and replay cached calculations. <a href="${routeFor('pxcube','atlas')}">Open Atlas →</a></div><div class="apps">${catalog.pxcubeResults.map(x=>`<div class="app-card"><div class="row spread"><h3>${esc(x.id)}</h3><span class="badge ${x.ok?'':'amber'}">${x.ok?'PACKAGED':'FAILED'}</span></div><p>Existing crisp build, chunk hashes and source pin. Human acceptance remains in the existing neat item.</p><div class="row"><a href="${routeFor('pxcube','run',`experiences/${x.id}/index.html`)}">Run leaf →</a><a href="compiled/pxcube/${esc(x.receipt)}" target="_blank" rel="noopener">Receipt</a></div></div>`).join('')}</div>`:p.id==='hh'?`<div class="apps">${workflows.map(x=>`<div class="app-card"><h3>${esc(x.title??x.name??x.id)}</h3><p>${esc(x.description)}</p><a href="${routeFor('hh','compose')}">Compose real service calls →</a></div>`).join('')}</div>`:`<div class="panel"><h2>Fixed, pinned, independently runnable</h2><p>Justin’s project remains a standalone leaf. Only the Tailwind dependency URL and broken hero asset reference were repaired for local static portability. No campaign content or outreach was changed.</p><div class="row"><a href="${routeFor('justin','run')}">Display the existing site →</a><a href="${routeFor('justin','audit')}">Open technical audit & annotations →</a></div></div>`}`;}
function compareView(p){$('#view').innerHTML=`<div class="notice">Recovered PageRouter’s original A/B switcher and side-by-side compare, now configured with these exact local compiled pins. The original URL-only configuration remains preserved in the rollback checkpoint.</div><iframe class="viewer" title="Recovered PageRouter comparison" sandbox="allow-scripts allow-same-origin" src="compare/index.html"></iframe>`;}
function runView(p){if(p.id==='justin')return renderJustinSiteIDE($('#view'),{project:p,baseURL,leaf:route.leaf||p.entry,implementationPin:catalog.release?.siteBuildId??catalog.release?.buildId});let leaf=route.leaf||p.entry;const url=new URL(`compiled/${p.id}/${leaf}`,baseURL);$('#view').innerHTML=`<div class="row spread"><div><span class="badge">COMPILED PIN</span><span class="mono"> ${esc(leaf)}</span></div><div class="row"><button id="reload-leaf">Reload</button><button id="full-project">Full project</button>${p.id==='justin'?`<a href="${routeFor('justin','audit')}">Audit & annotations</a>`:''}</div></div><div class="notice">${p.id==='hh'?'Synthetic fixture preview only. No real credentials, email or production data. HH’s existing DOM UI and real PxC runtime are running inside the compiled leaf.':p.id==='justin'?'Standalone technical snapshot. External links retain their original destination. Imported files are never allowed to run automatically.':'The full recovered PxCube launcher retains its own sandbox, clean/exp manifest review and existing lifecycle evidence. This is the real built launcher, not a replacement list.'}</div><iframe class="viewer" title="${esc(p.title)} compiled project" sandbox="${p.id==='justin'?'allow-scripts':'allow-scripts allow-same-origin allow-downloads allow-modals'}" src="${esc(url.href)}"></iframe>`;$('#reload-leaf').onclick=()=>{$('.viewer').src=url.href;};$('#full-project').onclick=()=>{location.hash=routeFor(p.id,'run');if(!route.leaf)$('.viewer').src=url.href;};}
function auditView(p){if(p.id!=='justin'){$('#view').innerHTML='<div class="panel"><h2>Technical audit</h2><p>The currently loaded technical audit belongs to Justin’s standalone site.</p><a href="'+routeFor('justin','audit')+'">Open Justin audit →</a></div>';return;}const direct=new URL('justin-audit/',baseURL);$('#view').innerHTML=`<div class="row spread"><div><span class="badge">TECHNICAL AUDIT</span><span class="mono"> Live-origin evidence, separately labeled from the local mirror</span></div><a id="direct-audit-link" href="${esc(direct.href)}" target="_blank" rel="noopener">Open shareable audit →</a></div><div class="notice">These findings concern the recorded live jkbrundage.com evidence. The runnable pinned mirror only has two local portability repairs; those do not establish that the live findings are fixed. No campaign deployment or content has been changed.</div><iframe class="viewer" title="Justin technical audit and issue annotations" sandbox="allow-scripts allow-downloads" src="justin-audit/index.html"></iframe>`;}
function unavailable(p,type){$('#view').innerHTML=`<div class="panel"><h2>${type==='functions'?'Project functionality':'Composition seam'}</h2><p>${p.id==='justin'?'Justin’s leaf deliberately has no forced HH composition. Its functionality is its existing six-page static navigation.':'PxCube’s original ${catalog.pxcubeResults.filter(x=>x.ok).length} experiences remain independently runnable in the recovered launcher. Their declared manifests and real scenes are inspected through the original UI. The HH service subtree supplies the workbench’s currently wired programmable composition seam.'}</p><div class="row"><a href="${routeFor(p.id,'run')}">Display & run →</a><a href="${routeFor('hh',type)}">Open HH ${type} →</a></div></div>`;}
function functionsView(p){if(p.id!=='hh')return unavailable(p,'functions');const c=capabilities.find(x=>x.id===selectedCapability);$('#view').innerHTML=`<div class="two"><div class="panel"><h2>Run functionality separately</h2><label class="field" for="capability">Actual HH capability</label><select id="capability">${capabilities.map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${esc(x.id)} · ${esc(x.port)}</option>`).join('')}</select><p>${esc(c.description)}</p><label class="field" for="cap-input">Inputs · JSON only</label><textarea id="cap-input">${esc(pretty(c.inputs.example??{}))}</textarea><div class="row" style="margin-top:15px"><button class="primary" id="invoke">Run capability</button><button id="test-functions">Test fixture surface</button></div><div id="function-status" role="status"></div></div><div class="panel"><h2>Actual output and provenance</h2><pre id="function-output">${esc(lastResult?pretty(output(lastResult)):'Run a capability to inspect its actual result.')}</pre><details class="details"><summary>Live PxC Parts & real receipts</summary><pre id="inspection">${esc(pretty(hh.inspect()))}</pre></details></div></div>`;$('#capability').onchange=e=>{selectedCapability=e.target.value;functionsView(p);};$('#invoke').onclick=async()=>{try{const input=JSON.parse($('#cap-input').value);lastResult=await hh.invoke(c.id,input);$('#function-output').textContent=pretty(output(lastResult));$('#inspection').textContent=pretty(hh.inspect());$('#function-status').innerHTML=`<div class="notice ${lastResult.ok?'':'error'}">${lastResult.ok?'Actual service output produced':'Service rejected the input or returned a known failure'} · ${esc(lastResult.receipt?.into??'no Calculation executed')}</div>`;}catch(e){$('#function-status').textContent=e.message;}};$('#test-functions').onclick=async()=>{const results=[];const fresh=createHHWorkbench({storage:{getItem:()=>null,setItem:()=>{},removeItem:()=>{}}});for(const id of ['school.states','school.counties','school.districts','school.schools','session.status','profile.public']){const selected=fresh.listCapabilities().find(x=>x.id===id);const r=await fresh.invoke(id,selected.inputs.example);results.push({capability:id,ok:r.ok,receipt:r.receipt?{status:r.receipt.status,into:r.receipt.into}:null,outcome:r.result?.outcome});}const compound=await fresh.compose({workflow:'schoolSearch',chooseFirst:true});results.push({composition:'schoolSearch',ok:compound.ok,actualStages:compound.outcomes.length});testsResult=results;$('#function-output').textContent=pretty(results);$('#function-status').textContent=`${results.filter(x=>x.ok).length}/${results.length} actual checks passed; rejected outcomes remain visible`;};}
function composeView(p){if(p.id!=='hh')return unavailable(p,'compose');const w=workflows.find(x=>x.id===selectedWorkflow)??workflows[0];if(!composeDraft)composeDraft=pretty(w.example??{workflow:w.id,chooseFirst:true});$('#view').innerHTML=`<div class="two"><div class="panel"><h2>Compose existing functionality</h2><label class="field" for="workflow">Start from a declared preset</label><select id="workflow">${workflows.map(x=>`<option value="${x.id}" ${x.id===w.id?'selected':''}>${esc(x.title??x.id)}</option>`).join('')}</select><p>Use workflow inputs, or an ordered stages array with {$ref:"stage.data.path"}. Values are explicitly bound into real kernel calls.</p><label class="field" for="composition-input">Composition · editable JSON</label><textarea id="composition-input">${esc(composeDraft)}</textarea><div class="row" style="margin-top:15px"><button class="primary" id="run-composition">Run composition</button><button id="save-composition">Download plan</button><button id="reset-fixture">Reset fixture</button></div><div id="composition-status" role="status"></div></div><div class="panel"><h2>Pipeline output and receipts</h2><div id="stages"></div><pre id="composition-output">${esc(lastResult?pretty(output(lastResult)):'Outputs appear here after actual composition.')}</pre><details class="details"><summary>Inspect the owning PxC</summary><pre id="composition-inspection">${esc(pretty(hh.inspect()))}</pre></details></div></div>`;$('#workflow').onchange=e=>{selectedWorkflow=e.target.value;composeDraft='';composeView(p);};$('#composition-input').oninput=e=>{composeDraft=e.target.value;};$('#run-composition').onclick=async()=>{try{lastResult=await hh.compose(JSON.parse($('#composition-input').value));$('#composition-output').textContent=pretty(output(lastResult));$('#composition-inspection').textContent=pretty(hh.inspect());$('#stages').innerHTML=(lastResult.outcomes??[]).map(s=>`<div class="stage"><strong>${esc(s.id)} → ${esc(s.operation)} · ${s.ok?'PRODUCED':'FAILED'}</strong><small>${esc(s.receipt?.into??'not executed')}</small></div>`).join('');$('#composition-status').innerHTML=`<div class="notice ${lastResult.ok?'':'error'}">${lastResult.ok?'Composition produced actual output':'Composition stopped or failed'} · outer receipt ${esc(lastResult.receipt?.status??'not executed')}</div>`;}catch(e){$('#composition-status').textContent=e.message;}};$('#save-composition').onclick=()=>download('hh-composition.json',JSON.parse($('#composition-input').value));$('#reset-fixture').onclick=async()=>{await hh.reset();lastResult=null;$('#composition-status').textContent='Disposable fixture state reset; seeded profiles retained';};const repl=document.createElement('div');repl.id='live-session';$('#view').prepend(repl);renderSessionREPL(repl,{hh,pin:p.digest,implementationPin:catalog.release?.buildId});}
function download(name,data){const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function deltaView(p){$('#view').innerHTML=`<div class="grid"><div class="panel"><div class="kicker">Verified local example</div><div class="big">${proof.payloadBytes} B</div><div class="metric-note">Changed compiled payload · ${proof.operations.length} output operation</div></div><div class="panel"><div class="kicker">Dependency build</div><div class="big">${proof.rebuilt.length} / ${proof.reused.length}</div><div class="metric-note">Rebuilt closure / reused targets · HH C6 CSS edit</div></div><div class="panel"><div class="kicker">Delta versus clean</div><div class="big proof">PASS</div><div class="metric-note">Exact files and digest matched in Node</div></div></div><div class="notice">Compiled patches carry exact baseline and target hashes. Every operation is validated before storage changes. Unknown imported code is rendered inert, with no script execution. The shipped verified HH delta can run after import.</div><div class="two"><div class="panel"><h2>Local change → smallest compiled span</h2><p>Edit the actual copied HH styles source, rebuild its declared dependency closure, and export the compiled delta. Existing PxCube compilation remains crisp’s responsibility.</p><div class="row"><button id="load-base">Load HH baseline</button><button id="load-example">Load verified delta example</button></div><label class="field" for="source-edit">HH styles.css · browser-native source</label><textarea id="source-edit" placeholder="Load HH baseline to edit its source copy">${deltaBase?esc(new TextDecoder().decode(fromBase64(deltaBase.files['styles.css'].data))):''}</textarea><div class="row" style="margin-top:15px"><button class="primary" id="build-delta" ${deltaBase?'':'disabled'}>Build local delta</button><button id="export-patch" ${lastPatch?'':'disabled'}>Download compiled patch</button></div><pre id="delta-build-output">${esc(pretty(proof))}</pre></div><div class="panel"><h2>Import and verify compiled patch</h2><label class="field" for="patch-file">Compiled patch JSON</label><input class="file-input" id="patch-file" type="file" accept=".json,application/json"><div class="row" style="margin-top:15px"><button id="apply-example">Import shipped HH delta</button><button id="wrong-base">Test wrong-baseline rejection</button><button id="preview-target" ${deltaTarget?'':'disabled'}>Display imported output</button></div><div id="delta-status" role="status">${deltaMessage?`<div class="notice">${esc(deltaMessage)}</div>`:''}</div><pre id="delta-import-output">${deltaTarget?esc(pretty({project:deltaTarget.project,digest:deltaTarget.digest,files:Object.keys(deltaTarget.files).length})): 'No patch applied yet. Baseline storage is immutable.'}</pre><div id="delta-preview"></div></div></div>`;$('#load-base').onclick=async()=>{deltaBase=await snapshot('hh');deltaView(p);};$('#load-example').onclick=async()=>{deltaBase=await snapshot('hh');lastPatch=await fetchJSON('data/hh.delta.json');const target=await fetchJSON('data/hh.target.json');$('#source-edit').value=new TextDecoder().decode(fromBase64(target.files['styles.css'].data));$('#build-delta').disabled=false;$('#export-patch').disabled=false;};$('#build-delta').onclick=async()=>{try{const sources=Object.fromEntries(Object.entries(deltaBase.files).map(([k,v])=>[k,{encoding:'base64',data:v.data}]));sources['styles.css']={encoding:'utf8',data:$('#source-edit').value};const spec=staticSpec('hh',sources);deltaTarget=await buildSnapshot(spec,{baseline:deltaBase});const clean=await buildSnapshot(spec);lastPatch=await createPatch(deltaBase,deltaTarget);const applied=await applyPatch(deltaBase,lastPatch);if(applied.digest!==clean.digest||canonical(applied.files)!==canonical(clean.files))throw Error('Clean-build equality failed');$('#delta-build-output').textContent=pretty({rebuilt:deltaTarget.build.rebuilt,reused:deltaTarget.build.reused,operations:lastPatch.ops.map(({data,...x})=>({...x,payloadBytes:fromBase64(data??'').length})),cleanBuildDigest:clean.digest,exactEqual:true});$('#export-patch').disabled=false;$('#delta-status').textContent='Local delta built; exact equality with clean build verified';}catch(e){$('#delta-status').textContent=`Rejected: ${e.message}`;}};$('#export-patch').onclick=()=>download('hh.compiled-patch.json',lastPatch);async function apply(patch){try{deltaBase=await snapshot(patch.project);const next=await applyPatch(deltaBase,patch);await saveSnapshot(next);deltaTarget=next;lastPatch=patch;deltaMessage=`Applied exact compiled patch. ${patch.ops.length} operations. ${known(next)?'Shipped trusted target, runnable.':'Unrecognized target, static inert preview only.'}`;deltaView(p);}catch(e){deltaMessage=`Rejected without applying: ${e.message}`;$('#delta-status').innerHTML=`<div class="notice error">${esc(deltaMessage)}</div>`;}}$('#patch-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>50000000){$('#delta-status').textContent='Rejected: patch exceeds limit';return;}try{await apply(JSON.parse(await f.text()));}catch(e){$('#delta-status').textContent=`Rejected: malformed JSON (${e.message})`;}};$('#apply-example').onclick=async()=>apply(await fetchJSON('data/hh.delta.json'));$('#wrong-base').onclick=async()=>{try{await applyPatch(await snapshot('justin'),await fetchJSON('data/hh.delta.json'));$('#delta-status').textContent='FAIL: wrong baseline accepted';}catch(e){$('#delta-status').textContent=`PASS: wrong baseline rejected before mutation · ${e.message}`;}};$('#preview-target').onclick=async()=>{if(!swReady){$('#delta-status').textContent='Local compiled preview requires service-worker support on HTTPS or localhost';return;}await saveSnapshot(deltaTarget);const url=new URL(`local-compiled/${deltaTarget.project}/${deltaTarget.digest}/index.html`,baseURL);$('#delta-preview').innerHTML=`<div class="notice">${known(deltaTarget)?'Trusted shipped delta running from validated browser-local storage':'Unknown code: inert sandbox preview, scripts and network disabled'}</div><iframe class="viewer" title="Imported compiled output" sandbox="${known(deltaTarget)?'allow-scripts allow-same-origin':''}"></iframe>`;const frame=$('#delta-preview iframe');if(known(deltaTarget))frame.src=url.href;else{const raw=new TextDecoder().decode(fromBase64(deltaTarget.files['index.html'].data));frame.srcdoc='<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; img-src data:; form-action \'none\'; base-uri \'none\'">'+raw;}};}
function known(s){return catalog.projects.some(p=>p.id===s.project&&p.digest===s.digest)||(catalog.knownTargets[s.project]??[]).includes(s.digest);}
function scopeView(p){const rows=[['Pinned project aggregation','Three real artifacts, exact hash/source pins and independent routes','IMPLEMENTED'],['Recovered PxCube launcher','12 actual crisp packages and inherited neat/tidy items; original launcher is independently runnable','BUILT'],['HH separate functionality','14 fixture ports; seven adapter checks passed with real Part/receipt pairing and failed receipt handling','TESTED'],['HH programmable composition','Visual typed node/input wiring, editable caller ports, named versioned Calculation Parts, nested reuse and exact-pin graph/session export/import','IMPLEMENTED'],['Compiled delta transport','Exact base/target, minimum one-splice changed bytes, adds/deletes, dependency closure, immutable acceptance','TESTED'],['Browser imported output','26 browser checks passed; shipped target runnable; hostile script/image denied by CSP in iframe and direct navigation','TESTED'],['Historical PageRouter recovery','Recovered original index, pinned configuration and deployment workflow at5cc1ae3d8d4d; original A/B compare retained','IMPLEMENTED'],['PxCube source delta proof','Existing crisp hello-source change: one packageKey rebuilt, eleven reused;46 output bytes patched; all12 compiled packages equal clean','TESTED'],['AnnotationFG concrete composition','Enable/disable event → hidden/visible state → registered pure seek projection, same leaf/composite contract shape and inspectable actual PxC wiring; no universal FG semantics claimed',catalog.annotationProof?.tested?'TESTED':'QA PENDING'],['Justin live site IDE','Nine dated issue mappings, page/viewport selection, five guarded presentation prototypes, undo/reset and exact-base typed export; assets, email delivery, citation sources and collapse focus behavior remain open',catalog.annotationProof?.tested?'TESTED':'QA PENDING'],['GitHub Pages publication','Authorized existing samuelpmahan/PageRouter; base workbench published at cbc7a00fe64f with successful Actions37075903349; old exact head preserved in rollback branch; annotation patch publication pending','PUBLISHED + PATCH QA']];$('#view').innerHTML=`<div class="notice">Evidence describes implemented behavior and exact remaining gaps. Builds and tests never promote an experiment or fabricate human acceptance. Existing neat items remain authoritative.</div><div class="panel"><h2>Expected scope ↔ actual evidence</h2><div class="data-list">${rows.map(([a,b,c])=>`<div class="data-item"><strong>${esc(a)}</strong><p>${esc(b)}</p><span class="badge ${['GAP','BLOCKED','UNDEFINED','IN PROGRESS','QA PENDING'].includes(c)?'amber':''}">${c}</span></div>`).join('')}</div></div><div class="notice">Justin annotation checks: ${catalog.annotationProof?.passed??0} passed, ${catalog.annotationProof?.failed??0} failed · <a href="data/annotation-verification.json" target="_blank" rel="noopener">Exact behavior checks & compatibility proof →</a></div><div class="section-title"><h2>Existing crisp dependency graph</h2><span>Recovered resolveTargets package inputs</span></div><div class="panel">${catalog.targets.map(x=>`<details class="details"><summary>${esc(x.id)} · ${x.packageKey.slice(0,12)}</summary><pre>${esc(pretty({packageKey:x.packageKey,inputs:x.inputs,reasons:x.reasons}))}</pre></details>`).join('')}</div><div class="section-title"><h2>Original lifecycle and receipts</h2></div><div class="panel"><p>The real recovered launcher links the existing neat/tidy board. This workbench doesn’t create a competing tracker.</p><a href="${routeFor('pxcube','run','neat.html')}">Open original neat lifecycle →</a><details class="details"><summary>Source snapshot provenance</summary><pre>${esc(pretty(catalog.lifecycle))}</pre></details><details class="details"><summary>Discovery and portability boundaries</summary><pre>${esc(pretty({discovery:catalog.sourceDiscovery,portability:catalog.portability}))}</pre></details></div>`;}
